   588	// CountOtherActiveSessionsWithCheckpoints counts how many other active sessions
   589	// from the SAME worktree (different from currentSessionID) have created checkpoints
   590	// on the SAME base commit (current HEAD). This is used to show an informational message
   591	// about concurrent sessions that will be included in the next commit.
   592	// Returns 0, nil if no such sessions exist.
   593	func (s *ManualCommitStrategy) CountOtherActiveSessionsWithCheckpoints(ctx context.Context, currentSessionID string) (int, error) {
   594		currentWorktree, err := paths.WorktreeRoot(ctx)
   595		if err != nil {
   596			return 0, fmt.Errorf("failed to get worktree root: %w", err)
   597		}
   598	
   599		// Get current HEAD to compare with session base commits
   600		repo, err := OpenRepository(ctx)
   601		if err != nil {
   602			return 0, err
   603		}
   604		defer repo.Close()
   605		head, err := repo.Head()
   606		if err != nil {
   607			return 0, fmt.Errorf("failed to get HEAD: %w", err)
   608		}
   609		currentHead := head.Hash().String()
   610	
   611		allStates, err := s.listAllSessionStates(ctx)
   612		if err != nil {
   613			return 0, err
   614		}
   615	
   616		count := 0
   617		for _, state := range allStates {
   618			// Only consider sessions from the same worktree with checkpoints
   619			// AND based on the same commit (current HEAD)
   620			// Sessions from different base commits are independent and shouldn't be counted
   621			if state.SessionID != currentSessionID &&
   622				state.WorktreePath == currentWorktree &&
   623				(state.StepCount > 0 || state.HasTaskContent()) &&
   624				state.BaseCommit == currentHead {
   625				count++
   626			}
   627		}
   628		return count, nil
   629	}
